import java.io.*;
import java.util.*;
public class G {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        TaskE solver = new TaskE();
        solver.solve(1, sc, pw);
        pw.flush(); pw.close();
    }
    static class TaskE {
        class MinCostMaxFlow {
            List<Edge>[] graph;
            Edge[][] edgesArr;
            int[] dist;
            int N, S, T, maxFlow, minCost;
            final int INF = Integer.MAX_VALUE / 100;

            class Edge {
                int u, flow, rev, cost;
                Edge(int u, int flow, int cost, int rev) {
                    this.u = u; this.flow = flow; this.cost = cost; this.rev = rev;
                }
            }

            void addEdge(int u, int v, int flow, int cost) {
                int lu = graph[u].size(), lv = graph[v].size();
                graph[u].add(new Edge(v, flow, cost, lv));
                graph[v].add(new Edge(u, 0, -cost, lu));
            }

            void convertToArray() {
                edgesArr = new Edge[N][];
                for (int i = 0; i < N; i++) {
                    edgesArr[i] = graph[i].toArray(new Edge[0]);
                    graph[i].clear();
                }
            }

            MinCostMaxFlow(int n, int s, int t) {
                N = n; S = s; T = t; maxFlow = 0; minCost = 0;
                graph = new ArrayList[N];
                for (int i = 0; i < N; i++) {
                    graph[i] = new ArrayList<>();
                }
                dist = new int[N];
            }

            boolean bellmanFord(boolean check) {
                Arrays.fill(dist, INF);
                dist[0] = 0;
                for (int i = 0; i < N - 1; i++) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : edgesArr[j]) {
                            if (e.flow == 0) continue;
                            if (dist[j] + e.cost < dist[e.u]) {
                                dist[e.u] = dist[j] + e.cost;
                            }
                        }
                    }
                }
                if (check) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : edgesArr[j]) {
                            if (e.flow == 0) continue;
                            if (dist[j] + e.cost < dist[e.u]) return false;
                        }
                    }
                }
                return true;
            }

            int[] node, visit, prv, prve, distMin;

            boolean simple() {
                node = new int[N];
                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                distMin = new int[N];
                Arrays.fill(distMin, INF);
                node[0] = S;
                distMin[0] = 0;
                int front = 1, back = 0;
                while (front != back) {
                    int u = node[back++];
                    if (back == N) back = 0;
                    visit[u] = 2;
                    for (int i = 0; i < edgesArr[u].length; i++) {
                        Edge e = edgesArr[u][i];
                        if (e.flow == 0) continue;
                        int cdist = distMin[u] + e.cost;
                        if (cdist < distMin[e.u]) {
                            if (visit[e.u] == 0) {
                                node[front++] = e.u;
                                if (front == N) front = 0;
                            } else if (visit[e.u] == 2) {
                                if (--back == -1) back += N;
                                node[back] = e.u;
                            }
                            visit[e.u] = 1;
                            prv[e.u] = u;
                            prve[e.u] = i;
                            distMin[e.u] = cdist;
                        }
                    }
                }
                return visit[T] != 0;
            }

            class Pair {
                int F, S;
                Pair(int f, int s) { F = f; S = s; }
            }

            boolean dijkstra() {
                Arrays.fill(dist, INF);
                Arrays.fill(visit, 0);
                prv = new int[N];
                prve = new int[N];
                PriorityQueue<Pair> pq = new PriorityQueue<>((A, B) -> Integer.compare(A.S, B.S));
                pq.add(new Pair(S, 0));
                dist[S] = 0;
                while (!pq.isEmpty()) {
                    Pair p = pq.poll();
                    if (dist[p.F] < p.S) continue;
                    int u = p.F;
                    visit[u] = 2;
                    for (int i = 0; i < edgesArr[u].length; i++) {
                        Edge e = edgesArr[u][i];
                        if (e.flow == 0) continue;
                        int cdist = p.S + e.cost + dist[u] - dist[e.u];
                        if (cdist < dist[e.u]) {
                            if (visit[e.u] == 2) return false;
                            pq.add(new Pair(e.u, cdist));
                            dist[e.u] = cdist;
                            prv[e.u] = u;
                            prve[e.u] = i;
                            visit[e.u] = 1;
                        }
                    }
                }
                return visit[T] != 0;
            }

            int augment() {
                int p = T, flowMin = INF;
                while (p != S) {
                    int pp = prv[p], pe = prve[p];
                    flowMin = Math.min(flowMin, edgesArr[pp][pe].flow);
                    p = pp;
                }
                p = T;
                while (p != S) {
                    int pp = prv[p], pe = prve[p];
                    edgesArr[pp][pe].flow -= flowMin;
                    int revIdx = edgesArr[pp][pe].rev;
                    edgesArr[p][revIdx].flow += flowMin;
                    p = pp;
                }
                maxFlow += flowMin;
                return flowMin;
            }

            boolean calSimple() {
                while (simple()) {
                    minCost += dist[T] * augment();
                }
                return true;
            }

            void updatePotential() {
                for (int i = 0; i < N; i++) {
                    if (visit[i] != 0) {
                        dist[i] += distMin[i] - dist[S];
                    }
                }
            }

            boolean calWithPotential() {
                while (dijkstra()) {
                    int min = dist[T] + dist[T] - dist[S];
                    minCost += min * augment();
                    updatePotential();
                }
                return true;
            }
        }
        int n, m, k, c, d, a[], f[];
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            n = in.nextInt(); m = in.nextInt(); k = in.nextInt(); c = in.nextInt(); d= in.nextInt();
            int maxl = n + k, T = n * maxl + 1;
            MinCostMaxFlow flow = new MinCostMaxFlow(T + 1, 0, T);
            a = new int[k + 1]; f = new int[n + 1];
            for (int i = 1; i <= k; i++) {
                a[i] = in.nextInt();
                f[a[i]]++;
            }
            for (int i = 1; i <= n; i++) {
                if (f[i] == 0) continue;
                flow.addEdge(0, i, f[i], 0);
            }
            for (int i = 2; i <= n; i++) {
                for (int l = 0; l < maxl - 1; l++) {
                    flow.addEdge(l * n + i, (l + 1) * n + i, k, c);
                }
            }
            for (int i = 1; i <= m; i++) {
                int a = in.nextInt(), b = in.nextInt();
                for (int l = 0; l < maxl - 1; l++) {
                    for (int p = 1; p <= k; p++) {
                        if (a != 1)
                            flow.addEdge(n * l + a, n * (l + 1) + b, 1, d * (2 * p - 1) + c);
                        if (b != 1)
                            flow.addEdge(n * l + b, n * (l + 1) + a, 1, d * (2 * p - 1) + c);
                    }
                }
            }
            for (int l = 1; l < maxl; l++) {
                flow.addEdge(l * n + 1, T, k, 0);
            }
            flow.convertToArray();
            flow.calSimple();
            if (flow.maxFlow != k) {
                out.println("BUG");
            } else {
                out.println(flow.minCost);
            }
        }
    }
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;
        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        boolean hasMoreTokens() {
            try {
                while (st == null || !st.hasMoreTokens()) {
                    String s = br.readLine();
                    if (s == null) return false;
                    st = new StringTokenizer(s);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
            return true;
        }
        public int nextInt() { return Integer.parseInt(next()); }
        public long nextLong() { return Long.parseLong(next()); }
        public double nextDouble() { return Double.parseDouble(next()); }
    }
}
